package main

import (
	"bufio"
	"fmt"
	"os"
)

func dfs(board [][]byte, r, c int) {
	if r < 0 || c < 0 || r >= len(board) || c >= len(board[0]) || board[r][c] != 'O' {
		return
	}

	board[r][c] = 'S'

	dfs(board, r+1, c)
	dfs(board, r-1, c)
	dfs(board, r, c+1)
	dfs(board, r, c-1)
}

// NÃO ALTERE A ASSINATURA DA FUNÇÃO solve
func solve(board [][]byte) {
	if len(board) == 0 {
		return
	}

	rows := len(board)
	cols := len(board[0])

	for r := 0; r < rows; r++ {
		if board[r][0] == 'O' { dfs(board, r, 0) }

		if board[r][cols-1] == 'O' { dfs(board, r, cols-1) }
	}
	for c := 0; c < cols; c++ {
		if board[0][c] == 'O' { dfs(board, 0, c) }

		if board[rows-1][c] == 'O' { dfs(board, rows-1, c) }
	}

	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if board[r][c] == 'O' {
				board[r][c] = 'X'
			} else if board[r][c] == 'S' {
				board[r][c] = 'O'
			}
		}
	}
}

// NÃO ALTERE A MAIN
func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	var nrows, ncols int
	fmt.Sscanf(scanner.Text(), "%d %d", &nrows, &ncols)
	board := make([][]byte, nrows)
	for i := 0; i < nrows; i++ {
		scanner.Scan()
		board[i] = []byte(scanner.Text())
	}
	solve(board)
	for _, row := range board {
		fmt.Println(string(row))
	}
}
